CREATE POLICY "admin can manage clearance records" ON "clearance_records" AS PERMISSIVE FOR ALL TO "authenticated" USING ((auth.jwt() -> 'user_metadata' -> 'custom_claims' -> 'roles' ->> 0 ) = 'Admin') WITH CHECK ((auth.jwt() -> 'user_metadata' -> 'custom_claims' -> 'roles' ->> 0 ) = 'Admin');